    if (closingBalances == null || closingBalances.isEmpty()) {
        throw new IllegalArgumentException("closingBalances list cannot be null or empty");
    }
    double sum = 0.0;
    for (Double balance : closingBalances) {
        if (balance == null) {
            throw new IllegalArgumentException("balance value cannot be null");
        }
        sum += balance;
    }
    double average = sum / closingBalances.size();
    return Math.round(average * 100.0) / 100.0;
}

